 */ 
scwin.SetWindowPos2 = function(ObjID, nLeft, nTop) {
	ObjID.style.left = nLeft;
	ObjID.style.top = nTop;

}

/**
	2008.01.17 김성일
	목록에서 조회창을 새창으로 띄울 경우, 부모창의 중앙으로 새창을 옮기는 기능.
	child onload에서 사용할 수 있음.
*/
/**
 * @method
 * @name MoveCenterOfParent
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.MoveCenterOfParent = function() {
	var parentWin = frame.Provider("../");
	var selfWin = frame.Provider("./");

	var nX = parentWin.XPos;
	var nY = parentWin.YPos;

	var nWidth = parentWin.Width;
	var nHeight = parentWin.Height;

	var selfWidth = selfWin.Width;
	var selfHeight = selfWin.Height;

	//alert("nX=" + nX + ",nY=" + nY + ",nWidth=" + nWidth + ",nHeight=" + nHeight);
	selfWin.XPos = (nWidth / 2) - (selfWidth / 2);
	selfWin.YPos = (nHeight / 2) - (selfHeight / 4);
}
/*
	2008.01.17 김성일
	id로 넘겨받은 obj에 담긴 에러 메세지를 alert 시킴.
*/
/**
 * @method
 * @name alert_error
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.alert_error = function(dtsObj) {
	var USER_DEFINE  = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK");
	for (var i = 0; i < USER_DEFINE.length; i++)
	{
		var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
		var j;
		for (j = 0; j < errorCount; j++) {
			$c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j)+ "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
		}		
	}			
} 
/*
	2008.01.17 김성일
	id로 넘겨받은 obj의 type과 naming rule에 따라 IF을 각각 호출하여 값을 가져옴.
*/
/**
 * @method
 * @name getObjectValue
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.getObjectValue = function(obj) {
    if (typeof obj != "object") {
        return;
    }

    if (typeof obj.getValue != "undefined" && typeof obj.getValue == "function") {
        return scwin.trim(obj.getValue());
    }
    return;
}

/*
2008.01.17 김성일
id로 넘겨받은 obj의 type과 naming rule에 따라 IF을 각각 호출하여 값을 가져옴.
*/
/**
 * @method
 * @name getObjectText
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.getObjectText = function(obj) {
    if (typeof obj == "object") {
        if (obj.getID().indexOf("cmb") > -1){
            return obj.getText();
        }
    }
    return ("");
}

/*
	2008.01.17 김성일
	id로 넘겨받은 obj의 type과 naming rule에 따라 IF을 각각 호출하여 값을 넣는다.
*/
/**
 * @method
 * @name setObjectValue
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.setObjectValue = function(obj, value) {
    if (typeof obj != "object") {
        return;
    }

    if (typeof obj.setValue != "undefined" && typeof obj.setValue == "function") {
        obj.setValue(value);
    }
    return;
}
/*
	2008.01.17 김성일
	String의 좌우 공백 제거
*/
/**
 * @method
 * @name trim
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.trim = function(str) {
	if (str == undefined || str == null) return "";
	str += "";
	return str.replace(/(^\s*)|(\s*$)/g, "");
}
/*
	2008.01.17 김성일
	String의 특정 문자열(문자)를 특정문자열(문자)로 바꿈.
*/
/**
 * @method
 * @name replaceAll
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.replaceAll = function(src_str, src_char, tar_char) {
	var reg = new RegExp(src_char, "ig");
	return src_str.replace(reg, tar_char);
}

/**
 * @method
 * @name fn_chkXss
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_chkXss = function(src_str) {
	var isOk = false;
	var invalidChars = "\\&<>";

	for (var i = 0; i < invalidChars.length; i++) {
	   if (src_str.indexOf(invalidChars.charAt(i) ) != -1) {
		   isOk = true;
		   break;
	   }
	}

	return isOk;
}

/*
	2008.01.21 김성일
	넘어온 값에 comma 표시
*/
/**
 * @method
 * @name FormatNumberEx
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.FormatNumberEx = function(v1) { // FormatNumberEx("3000", 3) return "3,000"
	if (v1 == "") return '';

	var v2 = 3;
	var v3 = "";
	var str = new Array();
	var isMinus = false;
	v1 = String(v1);

	if(v1.indexOf(".") > -1){
		v3 = v1.substring(v1.indexOf("."), v1.length);
		v1 = v1.substring(0,v1.indexOf("."));
	}
	if(v1.indexOf("-") == 0){
		v1 = v1.substring(1);
		isMinus = true;
	}

	for(var i = 1; i <= v1.length; i++)
	{
		if(i % v2) 
		{
			str[v1.length-i] = v1.charAt(v1.length - i);
		}
		else
		{
			str[v1.length-i] = ',' + v1.charAt(v1.length - i);
		}
	}

	str = str.join('').replace(/^,/,'');
	str = str + v3;
	if(isMinus){
		str = "-" + str;
	}
	return str;
}

/*
2020.05.07 김보영
넘어온 값에 comma 표시
0처리 안되서 FormatNumberEx 이걸 수정 하려고 했는데 사용하는데가 너무 많아서 하나 새로 만듦.
*/
/**
 * @method
 * @name FormatNumberExESG
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.FormatNumberExESG = function(v1) {  // FormatNumberEx("3000", 3) return "3,000"

//0, NaN, "", undefined, null 등은 모두 false 처리 됨 그래서 아랫 조건은 false == false이기 때문에 0이와도 빈값을 던짐.
if (v1 == "" && v1.length == 0) return '';
if (v1 == "" && v1.length == 1) return v1;

var v2 = 3;
var v3 = "";
var str = new Array();
v1 = String(v1);

if(v1.indexOf(".") > -1){
	v3 = v1.substring(v1.indexOf("."), v1.length);
	v1 = v1.substring(0,v1.indexOf("."));
}

for(var i = 1; i <= v1.length; i++)
{
	if(i % v2) 
	{
		str[v1.length-i] = v1.charAt(v1.length - i);
	}
	else
	{
		str[v1.length-i] = ',' + v1.charAt(v1.length - i);
	}
}

str = str.join('').replace(/^,/,'');
str = str + v3;

return str;
}


/**
 * @method
 * @name FormatDateEx
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.FormatDateEx = function(str) {
	if (str == "")return "";

	var yyyy = str.substring(0, 4);
	var mm = str.substring(4, 6);
	var dd = str.substring(6, 8);
	return yyyy + "-" + mm + "-" + dd;
}

