	//공통함수로 사용한다.
	/**
 * @method
 * @name ParseFeature
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.ParseFeature = function(vFeatures, fNameArray, fValueArray, fTypeArray) {
		var vFeatureArray = vFeatures.split(",");
		var vFeaturePair;

		for (var i = 0; i < vFeatureArray.length; i++) {

			vFeaturePair = vFeatureArray[i].split("=");

			for (var j = 0; j < fNameArray.length; j++) {
				if (vFeaturePair[0] == fNameArray[j]) {
					switch (fTypeArray[j]) {
						case "string" :
							fValueArray[j] = vFeaturePair[1];
							break;
						case "number" :
							fValueArray[j] = Number(vFeaturePair[1]);
							break;
						case "boolean" :
							if (vFeaturePair[1].toUpperCase() == "YES" || vFeaturePair[1].toUpperCase() == "TRUE" || vFeaturePair[1] == "1") {
								fValueArray[j] = true;
							} else {
								fValueArray[j] = false;
							}
							break;
					}
				}
			}
		}
	}


/*
* 조회조건에 기간선택하는 콤보박스 데이타 셋팅
*/	
/**
 * @method
 * @name Combo_CBDataSetPeriod
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.Combo_CBDataSetPeriod = function(svalComp) {

	var usrCBData ="기간선택^0||1주일전^1||1개월전^2||3개월전^3||6개월전^4||1년전^5||2년전^6" 
	//sval : 적용할 콤보 ID
	//sval.CBData =  usrCBData; //사용자CBData 지정
    //svalComp.removeAll();
    svalComp.removeAll();
    const defaultIndex = svalComp.itemArr.length;

	usrCBData.split("||").map(function (v,idx) {
        var itemSet =  v.split("^");
        svalComp.addItem(itemSet[1], itemSet[0], idx + defaultIndex);
    });

    svalComp.setSelectedIndex(0);
	//sval.Index=0; //CBDATA를 넣어주고 나서 첫 컬럼 지정한다.
}

/*
* from, to 날짜에 기간구분선택에 따른 날짜 셋팅하기   
*  - 기간구분 : pTp
*  - from 객체 이름 : pObjFrom
*  - to 객체 이름 : pObjTo
*/ 
/**
 * @method
 * @name fn_setFromToDate
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_setFromToDate = function(pTp, pObjFrom, pObjTo) {

	//1주일^1,1개월^2,3개월^3,6개월^4,1년^5,2년^6
	var vFrom = "";
	var vTo = scwin.getObjectValue(pObjTo);

	if(vTo == '') {	// 값이 없으면 현재일 기준으로 계산
		vTo = $c.utils.cGetToday("yyyymmdd");
	}

	if (pTp == 1) {
		vFrom = $c.utils.cGetMinusDate2(vTo, 7); 	// 일주일전		
	} else if (pTp == 2) {		// 1개월전
		vFrom = $c.utils.cGetMinusMonth(vTo.substring(0,4), vTo.substring(4,6), vTo.substring(6,8), 1);
	} else if (pTp == 3) {		// 3개월전
		vFrom = $c.utils.cGetMinusMonth(vTo.substring(0,4), vTo.substring(4,6), vTo.substring(6,8), 3);
	} else if (pTp == 4) {		// 6개월전
		vFrom = $c.utils.cGetMinusMonth(vTo.substring(0,4), vTo.substring(4,6), vTo.substring(6,8), 6);
	}  else if (pTp == 5) {	// 1년전
		vFrom = $c.utils.cGetMinusYear(vTo, 1);
	}  else if (pTp == 6) {	// 2년전
		vFrom = $c.utils.cGetMinusYear(vTo, 2);
	} else {
        vFrom = $c.utils.cGetMinusYear(vTo, 1);
    }

	scwin.setObjectValue(pObjFrom,  vFrom);
	scwin.setObjectValue(pObjTo, vTo );

}

