/**
 * @method
 * @name IsValidEmail
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.IsValidEmail = function(str) {
	var mailexp = /^[a-z][\w.-]+@\w[\w.-]+\.[\w.-]*[a-z][a-z]$/i;
	return mailexp.test(str);
}

/*
 * fn_getModalCenterPos: Modal gfm화면을 screen center로 표시하고자 할때 width, height를 고려하여 createDialogFrame에 인수로 전달
 * left, top 위치를 구한다.
 * return type이 pt.x, pt.y인 것에 주의
 */
/**
 * @method
 * @name fn_getModalCenterPos
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_getModalCenterPos = function(opnFrm, frmWth, frmHgt) {
	var pt = {x: 0, y: 0};

	pt.x = (window.screen.width / 2)  - opnFrm.screenLeft - (frmWth / 2);
	pt.y = (window.screen.height / 2) - opnFrm.screenTop  - (frmHgt / 2);

	return pt;
}

