/*
 * <미공개 공시뷰어 열기-당번의 부서직책이 팀원인경우 당번지정시간에만 조회, 처리기능 부여, 
 *                  당번의 부서직책이 팀장이면  타팀종목 조회,처리가능 >
 *  사용법
 *  - pAcptNo : 접수번호
 *  - pViewerStat : 처리버튼 생성타입 (R or P)
 *  - pEmpNo : 사원번호
 *  - pDepCd : 부서코드
 *  - pJobtitl : 부서직책
 *  - pDuty : 부서직책
 *  - pDutyChrg : 부서직책
 *  - pScrnTpCd : 화면구분코드(P=담당자검토, M=책임자승인, S=공시처리현황)
 *  - pDtsObj : 데이터셋
 *
 *  신규 : 2013.05.14
 */
/**
 * @method
 * @name fn_OpenNoDisclViewer
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.fn_OpenNoDisclViewer = function(pAcptNo, pViewerStat, pEmpNo, pDepCd, pJobtitl, pDuty, pDutyChrg, pScrnTpCd, pDtsObj, pScrenID) {

	var gDutyTimeYn = 'Y';

	var gNowDutyYn = ''; //현재시점 당번여부
	var gNowDutyStat = ''; //현재시점 당번상태 S:개시, E:마감, N:null
	var gProcsYn = '';
	var gTeamSameYn = '';

	//alert('[pDuty]='+pDuty+',[pDutyChrg]='+pDutyChrg+',[pDepCd]='+pDepCd)

	if (
			pDepCd == '2600' || //유가 공시부(당번계정)
			pDepCd == '2611' || //유가 공시서비스팀팀
			pDepCd == '2620' || //유가 공시1팀
			pDepCd == '2630' || //유가 공시2팀
			pDepCd == '2640' || //유가 공시3팀
			pDepCd == '2650' || //유가 공시4팀
			pDepCd == '2660' || //유가 지원TF팀
			pDepCd == '3400' || //코스닥 공시업무부(당번계정)
			pDepCd == '3420' || //코스닥 공시1팀
			pDepCd == '3430' || //코스닥 공시2팀
			pDepCd == '3440' || //코스닥 공시3팀
			pDepCd == '3460' || //코스닥 공시5팀
			pDepCd == '3490' || //코스닥 공시4팀2018.04.09
			pDepCd == '3495' || //코스닥 지원TF팀 2021.03.12
			pDepCd == '3470' || //코스닥 T1팀 2020.03.20
			pDepCd == '3480'   //코스닥 T2팀 2020.03.20
		) {


		if (pJobtitl == '09' || pJobtitl == '40') {
			//alert('pJobtitl.'+pJobtitl);
		} else {

			scwin.fn_checkDutyTimeStatus(pEmpNo, pAcptNo, pDtsObj);

			gNowDutyYn = pDtsObj.NameString(1, 'NOW_DUTY_YN'); //현재시점 당번여부
			gNowDutyStat = pDtsObj.NameString(1, 'NOW_DUTY_STAT'); //현재시점 당번상태 S:개시, E:마감, N:미등록
			gProcsYn = pDtsObj.NameString(1, 'PROCS_YN');
			gTeamSameYn = pDtsObj.NameString(1, 'TEAM_SAME_YN');

			if (gProcsYn == 'N') {

				if (gNowDutyYn == 'Y' || pDuty == 'Y' || pDutyChrg == 'Y') {
					if (gNowDutyYn == 'Y') {
						if (gNowDutyStat == 'S') {
						} else {
							if (pScrnTpCd == 'M' || gTeamSameYn != 'Y') { //책임자승인에서는 개시상태가 아니면 담당종목도 조회불가
								gDutyTimeYn = 'N';
								$c.win.alert('[당번업무 시작 권한 부여] 후에 공시조회/처리를 하실 수 있습니다.');
							}
						}
					} else {
						if (gTeamSameYn != 'Y') {
							gDutyTimeYn = 'N';
							$c.win.alert('[당번업무]가 종료되었습니다.');
						}
					}
				}
			}
		}

		/*
		alert('[pJobtitl]='+pJobtitl+','  
		+'\n\r[gDutyYn]='+gNowDutyYn+',' 
		+'\n\r[gNowDutyStat]='+gNowDutyStat+','  
		+'\n\r[gProcsStatCd]='+gProcsYn+','  
		+'\n\r[gTeamSameYn]='+gTeamSameYn+','
		+'\n\r[gDutyTimeYn]='+gDutyTimeYn);
		*/

	}

	if ( gDutyTimeYn == 'Y' ) {
		scwin.fn_OpenDisclViewer(pAcptNo, pViewerStat, pScrenID);
	}	
}


