/*
 * <pre>
 * 한글을 포함한 글자의 사이즈를 구하기 위한 함수.
 *
 * 1. 설 명
 *
 * 2. 특이사항
 *    
 * </pre>
 */
/**
 * @method
 * @name getStringSize
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.getStringSize = function(message) {
	var i, len = 0;

	for (i = 0; i < message.length; i++) {
		(message.charCodeAt(i) > 255)? len += 2 : len++;
	}

	return len;
}	

/*
 * TextBox 또는 TextArea 값이 비어 있는 체크
 */
/**
 * @method
 * @name checkEmptyValue
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.checkEmptyValue = async function(  obj  , msg ) {
	if( scwin.getObjectValue(obj) == "" ) {
		await $c.win.alert("[" + msg + "]를  입력하세요."); 
		obj.focus(); 
		return false; 
	}		
	return true;
}

/*
 * 일자체크후   buttonSet을 수정 또는 조회 상태할지 체크 하는 함수
 */
/**
 * @method
 * @name setButtonSetWithDate
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.setButtonSetWithDate = function(  obj, includeCurDate ) {
	var vCurDate = $c.utils.cGetToday("yyyymmdd");

//	buttonSet.setUpdateStatus(); 
//		return ;

	if(scwin.getObjectValue(obj) == "" ) {
		buttonSet.setUpdateStatus(); 
		return ;

	} else if( includeCurDate ) {
		if (vCurDate >  scwin.getObjectValue(obj)){ buttonSet.setErrorStatus(); } 
		else 	                            { buttonSet.setUpdateStatus();}

	} else {
		if (vCurDate >= scwin.getObjectValue(obj)){ buttonSet.setErrorStatus(); } 
		else 	                            { buttonSet.setUpdateStatus();}
	}
}

