/*
 * <pre>
 * max length 체크하기 위한 함수.
 *
 *	obj  : 체크하고자하는 object
 *  size : max length
 *  lbl  : 체크하고자 하는 항목의 label
 *    
 * </pre>
 */
/**
 * @method
 * @name checkMaxLength
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.checkMaxLength = function( obj , size , lbl ) {
	var overLen = eval( scwin.getStringSize( scwin.getObjectValue(obj) ) - size );

	if( overLen > 0 ) {
		$c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " 
				+ overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
		obj.focus();
		return false;
	}

	return true;
}	

/*
 * 시작일 , 종료일 이 같이 있을경우 
 * 시작일이 종료일 이전 일자인지 체크하기 위한 함수.
 *
 * 예)
 * fromMsg : 매매거래정지일
 * toMsg   : 매매거래해지일 
 */
/**
 * @method
 * @name compareFromToDate
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.compareFromToDate = function(fromDate,toDate,fromMsg,toMsg) {
	if( eval(scwin.getObjectValue(fromDate)) > eval(scwin.getObjectValue(toDate)) ) {
		$c.win.alert(fromMsg + "을(를) " + toMsg + " 이전으로 선택하세요.") ;
		return false ;
	}
	return true ;
}


/**
 * @method
 * @name compareFromToDate2
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.compareFromToDate2 = function(objSDate, objEDate) {
	if( eval(scwin.getObjectValue(objSDate)) > eval(scwin.getObjectValue(objEDate)) ) {
		$c.win.alert("검색시작일을  검색종료일 이전으로 선택하세요.") ;
		objSDate.focus();
		return false ;
	}
	return true ;
}
/*
	srcUrl과 찾을 id를 넘겨 값을 리턴 받는다.
	getQuery(frame.srcUrl, "ISUR_CD") => 00123;
*/
/**
 * @method
 * @name getQuery
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.getQuery = function(srcUrl, id) {
	if (srcUrl.indexOf("?") < 0) return "";

	var queryStr = srcUrl.split("?")[1];	
	var val = queryStr.split("&");
	for (var i = 0; i < val.length; i++) {
		var tmp = val[i].split("=");
		if (id == tmp[0]) {
			return tmp[1];
		}
	}
	return "";
}


/**
* 팝업의 left, top 좌표 구하가.
* 팝업 오픈 버튼 위치에 팝업창을 발생한다.
*/
/**
 * @method
 * @name getLeftTopPos
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.getLeftTopPos = function(pObjCtrl) {
    var aTag = pObjCtrl;
    var leftpos = 0;
    var toppos = 0;
    do {
        aTag = aTag.offsetParent;
        leftpos	+= aTag.offsetLeft;
        toppos  += aTag.offsetTop;
    } while(aTag.tagName!="BODY");

    var cleft =	pObjCtrl.offsetLeft + leftpos;
    var ctop  = pObjCtrl.offsetTop + pObjCtrl.offsetHeight + toppos;

    var arrPar = new Array();

    arrPar[0] = {   LEFT:cleft,
                    TOP:ctop
                };

    return arrPar;
}

/**
* 컴마찍기
*/
/**
 * @method
 * @name addComma
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.addComma = function(str) {
	var len = str.length;
	var s1 = "", s2 = "";
	if (len <= 3) {
		return str;
	} else {
		for(i = len-1 ; i >= 0; i--)
		s1 += str.charAt(i);

		for(i = len-1 ; i >= 0; i--){
			s2 += s1.charAt(i);
			if (i % 3 == 0 && i != 0)
				s2 += ",";
		}
		return s2;
	}
}

/*  '-145,123' 값에 대한 comma 찍기
 *  2010.03.29 - 안내문작성 시 변경주식수에 적용
 */
/**
 * @method
 * @name addCommaMinus
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.addCommaMinus = function(v1) {
	if (v1 == "") return '';

	var v2 = 3;
	var v3 = "";
	var str = new Array();
	v1 = String(v1);

	if(v1.indexOf("-") > -1){
		v3 = v1.substring(0,v1.indexOf("-")+1);
		v1 = v1.substring(v1.indexOf("-")+1,v1.length);
	}


	for(var i = 1; i <= v1.length; i++)	{
		if(i % v2 == 0 && i!=v1.length) {
			str[v1.length-i] = ',' + v1.charAt(v1.length - i);
		} else {
			str[v1.length-i] = v1.charAt(v1.length - i);
		}
	}

	str = str.join('').replace(/^,/,'');
	str = v3 + str;

	return str;
}

