//XMLHttpRequest객체	생성
/**
 * @method
 * @name createXMLObj4LogSave
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.createXMLObj4LogSave = function() {
    if (window.ActiveXObject) {
        xmlHttp4LogSave = new ActiveXObject("Microsoft.XMLHTTP");
    } else if (window.XMLHttpRequest) {
        xmlHttp4LogSave = new XMLHttpRequest();
    }
}	

//log저장을 위한 실제 URL 호출
/**
 * @method
 * @name startLogSave
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.startLogSave = function(ver1, ver2) {
	var url = "/common/logSaveAct.jsp?SCREN_ID=" +ver1+"&SCREN_PROCES_TP_CD="+ver2;
    xmlHttp4LogSave.onreadystatechange = scwin.chkStats4LogSave;	    
    xmlHttp4LogSave.open("GET", url, true);
    xmlHttp4LogSave.send(null);		    
}


/**
 * @method
 * @name chkStats4LogSave
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.chkStats4LogSave = function() {
    if (xmlHttp4LogSave.readyState == 4) {
        if (xmlHttp4LogSave.status == 200) {
            scwin.viewParameter4logSave();
        }
    }
}	

/**
 * @method
 * @name viewParameter4logSave
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.viewParameter4logSave = function() {
	var xmlDoc = xmlHttp4LogSave.responseXML;
	var node = xmlDoc.getElementsByTagName("result");	
	if (alert4LogSave)	$c.win.alert(node[0].childNodes[0].nodeValue);		
}	

/**
 * @method
 * @name doLogSave
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.doLogSave = function(ver1, ver2, ver3) {
	scwin.createXMLObj4LogSave();
	if (ver3)	alert4LogSave = true;
	scwin.startLogSave(ver1, ver2);
}

