/**
	매매거래정지 임시보관함 전송시 쓰이는 함수
 */

/**
 * @method
 * @name CopyDataSetForTemp
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.CopyDataSetForTemp = function(oOriginDataSet, oTargetDataSet, features) {
	var featureNames  = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
	var featureValues = [true, true, 1, oOriginDataSet.CountRow];
	var featureTypes  = ["boolean", "boolean", "number", "number"];

	if (features != null) {
		scwin.cfParseFeature(features, featureNames, featureValues, featureTypes);
	}
	var copyHeader  = featureValues[0];
	var resetStatus = featureValues[1];
	var rowFrom     = featureValues[2];
	var rowCnt      = featureValues[3];
	if (copyHeader == true) {
		scwin.CopyDataSetHeaderForTemp(oOriginDataSet, oTargetDataSet);
	}

	oTargetDataSet.ClearData();
	if (oOriginDataSet.CountRow > 0) {
		var temp = oTargetDataSet.dataid;  // importdata를 한 후 DataSet의 기존의 dataid 속성값이 지워지는 것을 방지.
		oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
		oTargetDataSet.dataid = temp;
		if (resetStatus == true) {
			oTargetDataSet.ResetStatus();
		}
	}	
}

/**
 * @method
 * @name CopyDataSetHeaderForTemp
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */ 
scwin.CopyDataSetHeaderForTemp = function(oOriginDataSet, oTargetDataSet) {
	var DsHeader = "";
	var colId   = "";
	var colType = "";
	var colProp = "";
	var colSize = "";
	var colDec = "";

	scwin.CopyDataSetHeaderDummy(oTargetDataSet);

	for (var i = 1; i <= oOriginDataSet.CountColumn; i++) {
 		colId   = oOriginDataSet.ColumnID(i);	     //column id
		colIndex= oOriginDataSet.ColumnIndex(colId);  //column id에 해당하는 index값	
		colSize = oOriginDataSet.ColumnSize(colIndex);//column size
		colDec = oOriginDataSet.ColumnDec(colIndex);//column size

	/* column의 type 정의 코드
			Type  Description
			-----------------
			 1    String 
			 2    Integer
			 3    Decimal
			 4    Date
			 5    URL
		*/
		//column type정의
		switch (oOriginDataSet.ColumnType(colIndex)){
		     case 1 :
		              colType = 'String';
		              break;
		     case 2 :
		              colType = 'Integer';
		              break;
		     case 3 :
		              colType = 'Decimal';
		              break;
		     case 4 :
		              colType = 'Date';
		              break;
		     case 5 :
		              colType = 'URL';
		              break;
		     case 9 :
		              colType = 'BIGINT';
		              break;

		     default :
		              colType = "";
		              break;
		}        

		/* column의 property 정의
			0 : Normal (Key = No)
			1 : Constant
			2 : Key (Normal, Sequence)
			3 : Sequence (Key = No) // 현재 의미없음.
		*/

		switch (oOriginDataSet.ColumnProp(i)) {
		     case 0 :
		              colProp = "NORMAL";
		              break;
		     case 1 :
		              colProp = "CONSTANT";
		              break;
		     case 2 :
		              colProp = "KEYVALUE";
		              break;
		     default :
		              colProp = "";
		              break;
		}        
		//column id,column type,column size, column property
		if(colType =="Decimal"){
			DsHeader = DsHeader + colId + ":" + colType + "(" + colSize +"."+colDec +")" + ":" + colProp + ",";
		}
		else{
			if(colId == "TRD_HALT_TP_NM"){
				colSize = 80;
			}
			DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + ")" + ":" + colProp + ",";
		}
	}

	DsHeader = DsHeader.substr(0, DsHeader.length - 1);
	oTargetDataSet.SetDataHeader(DsHeader);
}

